        org.junit.Assert.assertEquals("X should be updated", 50.0, point.x, 0.0001);
        org.junit.Assert.assertEquals("Y should be updated", 50.0, point.y, 0.0001);
        org.junit.Assert.assertEquals("Region should be INSIDE (0)", 0, point.region);

        // 4. Test Case: Top-Left Region
        // x (-10) < xMin -> LEFT (1)
        // y (150) > yMax -> TOP (8)
        // Expected Region: 1 | 8 = 9
        point.setPositionAndRegion(-10, 150);
